"""Report domain entity representing final synthesized intelligence and validated citations."""

from __future__ import annotations

import uuid
from typing import TYPE_CHECKING, Any

from sqlalchemy import ForeignKey, String, Text, UniqueConstraint, Uuid
from sqlalchemy.orm import Mapped, mapped_column, relationship

from app.db.base import Base, JSONBType, TimestampMixin, generate_uuid

if TYPE_CHECKING:
    from app.models.run import Run


class Report(Base, TimestampMixin):
    """Final research deliverable generated by the synthesis engine with grounding citations."""

    __tablename__ = "reports"

    id: Mapped[uuid.UUID] = mapped_column(
        Uuid,
        primary_key=True,
        default=generate_uuid,
        nullable=False,
    )
    run_id: Mapped[uuid.UUID] = mapped_column(
        Uuid,
        ForeignKey("runs.id", ondelete="CASCADE"),
        unique=True,
        nullable=False,
        index=True,
    )
    title: Mapped[str] = mapped_column(
        String(255),
        nullable=False,
    )
    markdown_content: Mapped[str] = mapped_column(
        Text,
        nullable=False,
    )
    executive_summary: Mapped[str] = mapped_column(
        Text,
        nullable=False,
    )
    citations: Mapped[list[dict[str, Any]]] = mapped_column(
        JSONBType,
        default=list,
        nullable=False,
    )
    metadata_payload: Mapped[dict[str, Any]] = mapped_column(
        JSONBType,
        default=dict,
        nullable=False,
    )

    # Relationships
    run: Mapped[Run] = relationship(
        "Run",
        back_populates="report",
    )

    __table_args__ = (UniqueConstraint("run_id", name="uq_reports_run_id"),)

    def __repr__(self) -> str:
        return f"<Report(id={self.id}, run_id={self.run_id}, title='{self.title[:30]}...')>"
